def is_valid(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    current = list(s)
    changed = True
    while changed:
        changed = False
        reduced = []
        i = 0
        while i < len(current):
            if i + 1 < len(current) and current[i] in "([{" and pairs.get(current[i + 1]) == current[i]:
                i += 2
                changed = True
            else:
                reduced.append(current[i])
                i += 1
        current = reduced
    return len(current) == 0
